[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&family=Righteous&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --purple-light: #9B7BFA;
      --orange: #FF7A00;
      --orange-light: #FF9A40;
      --pink: #FF3B7B;
      --white: #FFFFFF;
      --gray-50: #F8FAFC;
      --gray-100: #F1F5F9;
      --gray-200: #E2E8F0;
      --gray-300: #CBD5E1;
      --gray-400: #94A3B8;
      --gray-500: #64748B;
      --gray-600: #475569;
      --gray-700: #334155;
      --gray-800: #1E293B;
      --gray-900: #0F172A;
      --font-display: 'Righteous', sans-serif;
      --font-body: 'Poppins', sans-serif;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 2px 8px rgba(0,0,0,0.08);
      --shadow-md: 0 4px 16px rgba(0,0,0,0.12);
      --shadow-lg: 0 8px 32px rgba(0,0,0,0.16);
      --transition: 200ms ease;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: var(--font-body);
      background: var(--white);
      color: var(--gray-800);
      line-height: 1.6;
      overflow-x: hidden;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--gray-200);
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .header-logo {
      font-family: var(--font-display);
      font-size: 28px;
      color: var(--black);
      text-decoration: none;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .header-logo svg {
      width: 36px;
      height: 36px;
    }

    .header-nav {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .header-nav a {
      font-size: 15px;
      font-weight: 500;
      color: var(--gray-700);
      text-decoration: none;
      transition: color var(--transition);
    }

    .header-nav a:hover {
      color: var(--purple);
    }

    .btn-login {
      background: var(--black);
      color: var(--white) !important;
      padding: 10px 24px;
      border-radius: 100px;
      font-weight: 600 !important;
      transition: transform var(--transition), background var(--transition);
      cursor: pointer;
    }

    .btn-login:hover {
      background: var(--purple);
      transform: translateY(-1px);
    }

    .hamburger {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
      z-index: 200;
    }

    .hamburger svg {
      width: 28px;
      height: 28px;
      color: var(--black);
    }

    .mobile-nav {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 150;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 32px;
      opacity: 0;
      pointer-events: none;
      transition: opacity 300ms ease;
    }

    .mobile-nav.active {
      opacity: 1;
      pointer-events: auto;
    }

    .mobile-nav a {
      font-size: 24px;
      font-weight: 600;
      color: var(--gray-800);
      text-decoration: none;
      transition: color var(--transition);
    }

    .mobile-nav a:hover {
      color: var(--purple);
    }

    .mobile-nav .btn-login {
      margin-top: 16px;
    }

    /* Hero */
    .hero {
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      text-align: center;
      padding: 120px 24px 80px;
      background: linear-gradient(135deg, #0a0a0a 0%, #1a0a2e 50%, #2a1040 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      left: -50%;
      width: 200%;
      height: 200%;
      background: radial-gradient(circle at 30% 50%, rgba(118, 56, 250, 0.3) 0%, transparent 50%),
                  radial-gradient(circle at 70% 50%, rgba(255, 122, 0, 0.2) 0%, transparent 50%),
                  radial-gradient(circle at 50% 80%, rgba(255, 59, 123, 0.2) 0%, transparent 40%);
      animation: heroGlow 15s ease-in-out infinite;
    }

    @keyframes heroGlow {
      0%, 100% { transform: translate(0, 0) rotate(0deg); }
      33% { transform: translate(-5%, 3%) rotate(2deg); }
      66% { transform: translate(3%, -5%) rotate(-2deg); }
    }

    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 900px;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.2);
      padding: 8px 16px;
      border-radius: 100px;
      color: var(--white);
      font-size: 14px;
      font-weight: 500;
      margin-bottom: 32px;
    }

    .hero-badge svg {
      width: 16px;
      height: 16px;
    }

    .hero h1 {
      font-family: var(--font-display);
      font-size: clamp(40px, 8vw, 72px);
      color: var(--white);
      line-height: 1.1;
      margin-bottom: 24px;
    }

    .hero p {
      font-size: clamp(18px, 3vw, 22px);
      color: rgba(255,255,255,0.8);
      max-width: 600px;
      margin: 0 auto 40px;
      font-weight: 300;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: linear-gradient(135deg, var(--purple) 0%, var(--pink) 100%);
      color: var(--white);
      padding: 16px 40px;
      border-radius: 100px;
      font-size: 18px;
      font-weight: 600;
      text-decoration: none;
      border: none;
      cursor: pointer;
      transition: transform var(--transition), box-shadow var(--transition);
    }

    .btn-primary:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 30px rgba(118, 56, 250, 0.5);
    }

    .hero-scroll-hint {
      position: absolute;
      bottom: 40px;
      left: 50%;
      transform: translateX(-50%);
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 8px;
      color: rgba(255,255,255,0.5);
      font-size: 13px;
      animation: bounce 2s ease-in-out infinite;
    }

    @keyframes bounce {
      0%, 100% { transform: translateX(-50%) translateY(0); }
      50% { transform: translateX(-50%) translateY(8px); }
    }

    /* Section Base */
    .section {
      padding: 100px 24px;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
    }

    .section-label {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      color: var(--purple);
      margin-bottom: 16px;
    }

    .section-label svg {
      width: 16px;
      height: 16px;
    }

    .section-title {
      font-family: var(--font-display);
      font-size: clamp(32px, 5vw, 48px);
      color: var(--gray-900);
      line-height: 1.2;
      margin-bottom: 24px;
    }

    .section-title.gradient {
      background: linear-gradient(135deg, var(--purple) 0%, var(--orange) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .section-link {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-size: 16px;
      font-weight: 600;
      color: var(--purple);
      text-decoration: none;
      transition: gap var(--transition);
    }

    .section-link:hover {
      gap: 12px;
    }

    .section-link svg {
      width: 18px;
      height: 18px;
    }

    /* Features */
    .features {
      background: var(--gray-50);
    }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 24px;
      margin-top: 60px;
    }

    .feature-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 32px;
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-200);
      transition: transform var(--transition), box-shadow var(--transition);
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .feature-icon {
      width: 56px;
      height: 56px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .feature-icon svg {
      width: 28px;
      height: 28px;
    }

    .feature-icon.purple { background: rgba(118, 56, 250, 0.1); color: var(--purple); }
    .feature-icon.orange { background: rgba(255, 122, 0, 0.1); color: var(--orange); }
    .feature-icon.pink { background: rgba(255, 59, 123, 0.1); color: var(--pink); }

    .feature-card h3 {
      font-size: 20px;
      font-weight: 700;
      color: var(--gray-900);
      margin-bottom: 12px;
    }

    .feature-card p {
      font-size: 15px;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* Safety */
    .safety {
      background: linear-gradient(180deg, #f0f4ff 0%, var(--white) 100%);
    }

    .safety-content {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }

    .safety-text {
      max-width: 520px;
    }

    .safety-description {
      font-size: 18px;
      color: var(--gray-600);
      line-height: 1.7;
      margin-bottom: 32px;
    }

    .safety-visual {
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .safety-phone {
      width: 280px;
      height: 560px;
      background: var(--black);
      border-radius: 40px;
      padding: 12px;
      box-shadow: var(--shadow-lg);
    }

    .safety-phone-screen {
      width: 100%;
      height: 100%;
      background: linear-gradient(180deg, var(--purple) 0%, var(--pink) 100%);
      border-radius: 32px;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
    }

    .safety-phone-content {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 16px;
      padding: 40px;
      text-align: center;
    }

    .safety-phone-content svg {
      width: 48px;
      height: 48px;
      color: var(--white);
    }

    .safety-phone-content span {
      color: var(--white);
      font-size: 14px;
      font-weight: 600;
    }

    .safety-shield {
      position: absolute;
      width: 120px;
      height: 120px;
      background: var(--white);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-lg);
      right: -20px;
      top: 50%;
      transform: translateY(-50%);
    }

    .safety-shield svg {
      width: 56px;
      height: 56px;
      color: var(--purple);
    }

    /* Creators */
    .creators {
      background: var(--gray-900);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }

    .creators::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: radial-gradient(circle at 20% 80%, rgba(118, 56, 250, 0.4) 0%, transparent 50%),
                  radial-gradient(circle at 80% 20%, rgba(255, 122, 0, 0.3) 0%, transparent 50%);
    }

    .creators .container {
      position: relative;
      z-index: 1;
    }

    .creators .section-title {
      color: var(--white);
    }

    .creators-description {
      font-size: 18px;
      color: rgba(255,255,255,0.7);
      max-width: 600px;
      margin-bottom: 40px;
      line-height: 1.7;
    }

    .creators-stats {
      display: flex;
      gap: 48px;
      flex-wrap: wrap;
      margin-top: 60px;
    }

    .creator-stat {
      text-align: left;
    }

    .creator-stat-number {
      font-family: var(--font-display);
      font-size: 56px;
      background: linear-gradient(135deg, var(--purple) 0%, var(--pink) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .creator-stat-label {
      font-size: 15px;
      color: rgba(255,255,255,0.6);
      margin-top: 4px;
    }

    /* Tagline Banner */
    .tagline-banner {
      background: linear-gradient(135deg, var(--purple) 0%, var(--pink) 50%, var(--orange) 100%);
      padding: 80px 24px;
      text-align: center;
    }

    .tagline-text {
      font-family: var(--font-display);
      font-size: clamp(32px, 6vw, 56px);
      color: var(--white);
      line-height: 1.2;
    }

    /* News */
    .news {
      background: var(--gray-50);
    }

    .news-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      margin-bottom: 40px;
      flex-wrap: wrap;
      gap: 16px;
    }

    .news-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      padding-bottom: 16px;
      margin: 0 -24px;
      padding-left: 24px;
      padding-right: 24px;
    }

    .news-carousel::-webkit-scrollbar {
      display: none;
    }

    .news-card {
      flex: 0 0 340px;
      scroll-snap-align: start;
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-200);
      transition: transform var(--transition), box-shadow var(--transition);
      cursor: pointer;
    }

    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-md);
    }

    .news-thumb {
      width: 100%;
      height: 200px;
      object-fit: cover;
      background: linear-gradient(135deg, var(--purple) 0%, var(--pink) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .news-thumb svg {
      width: 48px;
      height: 48px;
      color: rgba(255,255,255,0.5);
    }

    .news-body {
      padding: 24px;
    }

    .news-tags {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
      margin-bottom: 12px;
    }

    .news-tag {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      padding: 4px 10px;
      border-radius: 100px;
      background: rgba(118, 56, 250, 0.1);
      color: var(--purple);
    }

    .news-tag.safety-tag {
      background: rgba(255, 59, 123, 0.1);
      color: var(--pink);
    }

    .news-title {
      font-size: 17px;
