      color: var(--gray-900);
      margin-bottom: 12px;
    }

    .cta-subheadline {
      font-size: 20px;
      color: var(--gray-500);
      margin-bottom: 40px;
    }

    .app-buttons {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .app-btn {
      display: inline-flex;
      align-items: center;
      gap: 12px;
      background: var(--black);
      color: var(--white);
      padding: 14px 28px;
      border-radius: var(--radius-md);
      text-decoration: none;
      transition: transform var(--transition), background var(--transition);
