      background: var(--gray-900);
      color: var(--white);
      padding: 80px 24px 40px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
      gap: 48px;
      max-width: 1200px;
      margin: 0 auto 60px;
    }

    .footer-col h4 {
      font-size: 14px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      margin-bottom: 20px;
      color: var(--white);
