      list-style: none;
    }

    .footer-col li {
      margin-bottom: 12px;
    }

    .footer-col a {
      color: var(--gray-400);
      text-decoration: none;
      font-size: 14px;
      transition: color var(--transition);
    }

    .footer-col a:hover {
      color: var(--white);
    }

    .footer-col a svg {
      width: 12px;
      height: 12px;
      margin-left: 4px;
      opacity: 0.5;
    }

    .footer-bottom {
      max-width: 1200px;
      margin: 0 auto;
      padding-top: 40px;
      border-top: 1px solid var(--gray-800);
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 24px;
    }

    .footer-meta {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .footer-logo {
      font-family: var(--font-display);
      font-size: 24px;
      color: var(--white);
    }

    .language-selector {
      display: flex;
      align-items: center;
      gap: 8px;
      background: var(--gray-800);
      border: none;
      color: var(--gray-300);
      padding: 10px 16px;
      border-radius: var(--radius-sm);
      font-size: 14px;
      cursor: pointer;
    }

    .language-selector svg {
      width: 16px;
      height: 16px;
    }

    .social-links {
      display: flex;
      gap: 16px;
    }

    .social-links a {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: var(--gray-800);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      transition: background var(--transition), color var(--transition);
    }

    .social-links a:hover {
      background: var(--purple);
      color: var(--white);
    }

    .social-links svg {
      width: 20px;
      height: 20px;
    }

    .legal-links {
      display: flex;
      gap: 24px;
      flex-wrap: wrap;
    }

    .legal-links a {
      color: var(--gray-500);
      text-decoration: none;
      font-size: 13px;
      transition: color var(--transition);
    }

    .legal-links a:hover {
      color: var(--white);
    }

