      .safety-content {
        grid-template-columns: 1fr;
        gap: 40px;
      }

      .safety-visual {
        order: -1;
      }
    }

    @media (max-width: 768px) {
      .header-nav {
        display: none;
      }

      .hamburger {
        display: block;
      }

      .mobile-nav {
        display: flex;
      }

      .section {
        padding: 60px 20px;
      }

      .hero {
        padding: 100px 20px 60px;
      }

      .news-carousel {
        margin: 0 -20px;
        padding-left: 20px;
        padding-right: 20px;
      }

      .news-card {
        flex: 0 0 300px;
      }

      .creators-stats {
        gap: 32px;
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 32px;
      }

      .footer-bottom {
        flex-direction: column;
        text-align: center;
      }
    }

    @media (max-width: 480px) {
      .news-card {
        flex: 0 0 280px;
      }

      .footer-grid {
        grid-template-columns: 1fr;
      }

      .footer-col {
        text-align: center;
      }
    }

    /* Reduced motion */
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }

      html {
        scroll-behavior: auto;
      }
    }
